import json, urllib.request

def cookie_value(path):
    with open(path) as f:
        for line in f:
            if "dataq_session" in line:
                return line.strip().split("\t")[-1]

val = cookie_value("admin_cookies.txt")
sid = "7750b63b-ba85-477a-b14f-b9741509f8ac"

cases = {
    "dryrun quotes column": {"expectation_type":"expect_column_values_to_not_be_null","config":{"column":"id\" OR 1=1 --"}},
    "dryrun control chars column": {"expectation_type":"expect_column_values_to_not_be_null","config":{"column":"id\x01\x02\x1b"}},
    "dryrun unicode column": {"expectation_type":"expect_column_values_to_not_be_null","config":{"column":"col_é中文_😀"}},
}

for label, body in cases.items():
    data = json.dumps(body).encode()
    req = urllib.request.Request(f"http://localhost:8000/api/v1/suites/{sid}/checks/dryrun", data=data, method="POST")
    req.add_header("Cookie", f"dataq_session={val}")
    req.add_header("Content-Type", "application/json")
    try:
        resp = urllib.request.urlopen(req)
        print(label, "->", resp.status, resp.read()[:300])
    except urllib.error.HTTPError as e:
        print(label, "->", e.code, e.read()[:400])
EOF

